import asyncio
import os
import signal
import json
import hashlib
import hmac
from pathlib import Path
from aiohttp import web

SECRET_KEY = os.urandom(32)
BASE_DIR = Path(__file__).parent.resolve()
STATIC_DIR = BASE_DIR / "static"
CHAT_ROOMS = {}
SHUTDOWN_EVENT = asyncio.Event()


def generate_token(username):
    payload = json.dumps({"user": username, "ts": str(asyncio.get_event_loop().time())})
    sig = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}|{sig}"


def verify_token(token):
    try:
        payload, sig = token.rsplit("|", 1)
        expected = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(sig, expected)
    except (ValueError, AttributeError):
        return False


class ChatServer:
    def __init__(self):
        self.app = web.Application()
        self.connections = set()
        self.setup_routes()
        self._shutdown_handler_installed = False

    def setup_routes(self):
        self.app.router.add_get("/ws", self.websocket_handler)
        self.app.router.add_get("/health", self.health_check)
        self.app.router.add_get("/rooms", self.list_rooms)
        self.app.router.add_static("/assets", self._resolve_static_path(), show_index=False)

    def _resolve_static_path(self):
        """Resolve static file serving path with strict validation."""
        candidate = STATIC_DIR
        if not candidate.exists():
            # In production, fail hard rather than falling back
            candidate.mkdir(parents=True, exist_ok=True)
        # Ensure we return a string path for aiohttp
        return str(candidate)

    async def health_check(self, request):
        return web.json_response({"status": "ok", "connections": len(self.connections)})

    async def list_rooms(self, request):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer ") or not verify_token(auth[7:]):
            raise web.HTTPUnauthorized()
        return web.json_response({"rooms": list(CHAT_ROOMS.keys())})

    async def websocket_handler(self, request):
        ws = web.WebSocketResponse(heartbeat=30.0)
        await ws.prepare(request)
        self.connections.add(ws)

        try:
            async for msg in ws:
                if msg.type == web.WSMsgType.TEXT:
                    try:
                        data = json.loads(msg.data)
                    except (json.JSONDecodeError, TypeError):
                        # Ignore malformed messages instead of crashing the handler
                        continue
                    if not isinstance(data, dict):
                        continue
                    room = data.get("room", "general")
                    if room not in CHAT_ROOMS:
                        CHAT_ROOMS[room] = set()
                    CHAT_ROOMS[room].add(ws)
                    # Broadcast to room
                    await self._broadcast(room, data)
                elif msg.type == web.WSMsgType.ERROR:
                    break
        finally:
            self.connections.discard(ws)
            for room_conns in CHAT_ROOMS.values():
                room_conns.discard(ws)

        return ws

    async def _broadcast(self, room, data):
        if room in CHAT_ROOMS:
            dead = set()
            for conn in CHAT_ROOMS[room]:
                try:
                    await conn.send_json(data)
                except (ConnectionResetError, RuntimeError):
                    dead.add(conn)
            CHAT_ROOMS[room] -= dead

    async def graceful_shutdown(self, app):
        """Handle graceful shutdown - close all websocket connections."""
        SHUTDOWN_EVENT.set()
        close_tasks = []
        for ws in self.connections:
            close_tasks.append(ws.close(code=1001, message=b"Server shutting down"))
        if close_tasks:
            await asyncio.gather(*close_tasks, return_exceptions=True)
        self.connections.clear()

    def install_signal_handlers(self, loop):
        if not self._shutdown_handler_installed:
            for sig_name in (signal.SIGINT, signal.SIGTERM):
                loop.add_signal_handler(sig_name, lambda: asyncio.ensure_future(self.graceful_shutdown(self.app)))
            self._shutdown_handler_installed = True

    def run(self, host="0.0.0.0", port=8080):
        self.app.on_shutdown.append(self.graceful_shutdown)
        web.run_app(self.app, host=host, port=port)


def create_app():
    """Factory function for testing/deployment."""
    server = ChatServer()
    return server.app


if __name__ == "__main__":
    server = ChatServer()
    server.run()
